use std::net::{TcpListener,TcpStream};use std::io::{Read,Write};use std::sync::{Arc,atomic::{AtomicUsize,AtomicBool,Ordering}};use std::time::{Duration,Instant};use std::thread;
#[test]fn stalled_clients_then_valid_recovery(){let l=TcpListener::bind("127.0.0.1:0").unwrap();let addr=l.local_addr().unwrap();l.set_nonblocking(true).unwrap();let stop=Arc::new(AtomicBool::new(false));let active=Arc::new(AtomicUsize::new(0));let st=stop.clone();let ac=active.clone();let server=thread::spawn(move||{while !st.load(Ordering::Relaxed){match l.accept(){Ok((mut s,_))=>{let now=Instant::now();if ac.fetch_add(1,Ordering::Relaxed)>=8192{ac.fetch_sub(1,Ordering::Relaxed);continue}let a=ac.clone();if thread::Builder::new().stack_size(131072).spawn(move||{let mut temp=[0u8;4096];let rem=Duration::from_secs(1).checked_sub(now.elapsed()).unwrap();let _=s.set_read_timeout(Some(rem));let _=s.read(&mut temp);a.fetch_sub(1,Ordering::Relaxed);}).is_err(){ac.fetch_sub(1,Ordering::Relaxed);}},Err(e)if e.kind()==std::io::ErrorKind::WouldBlock=>thread::sleep(Duration::from_millis(1)),Err(_)=>break}}});let mut clients=Vec::new();for _ in 0..128{let mut s=TcpStream::connect(addr).unwrap();s.write_all(b"GET /hello").unwrap();clients.push(s);}thread::sleep(Duration::from_millis(100));drop(clients);thread::sleep(Duration::from_millis(100));let mut s=TcpStream::connect(addr).unwrap();s.write_all(b"GET /hello HTTP/1.1\r\n\r\n").unwrap();stop.store(true,Ordering::Relaxed);server.join().unwrap();}
